// Safely get wallet address with fallback
let walletAddress;

try {
  // Try to get from Edit Fields node
  const editFieldsData = $('Edit Fields').first().json;
  walletAddress = editFieldsData.walletAddress;
} catch (e1) {
  try {
    // Try to get from Set node
    const setData = $('Set').first().json;
    walletAddress = setData.walletAddress;
  } catch (e2) {
    // Try from current input
    walletAddress = $input.first().json.walletAddress;
  }
}

// Remove 0x prefix if present and convert to lowercase
const cleanAddress = walletAddress.replace('0x', '').toLowerCase();

// Pad address to 64 characters for the function call
const paddedAddress = cleanAddress.padStart(64, '0');

// balanceOf function signature (0x70a08231)
const functionSignature = "70a08231";

// Complete encoded data
const encodedData = "0x" + functionSignature + paddedAddress;

// USDT contract address on BSC
const usdtContract = "0x55d398326f99059fF775485246999027B3197955";

return [{
  json: {
    walletAddress: "0x" + cleanAddress,
    usdtContract: usdtContract,
    encodedData: encodedData
  }
}];

// Get the USDT balance result from the previous HTTP Request
const balanceHex = $input.first().json.result;

console.log("Raw USDT hex result:", balanceHex);

// Handle null or undefined
if (!balanceHex || balanceHex === "0x" || balanceHex === "0x0") {
  return [{
    json: {
      balanceRaw: "0",
      balanceUSDT: 0,
      balanceFormatted: "$0.00 USDT",
      message: "⚠️ Wallet has 0 USDT on BSC",
      timestamp: new Date().toISOString()
    }
  }];
}

// Convert from hex to decimal
const balanceRaw = parseInt(balanceHex, 16);

// USDT on BSC has 18 decimals
const balanceUSDT = balanceRaw / 1000000000000000000;

return [{
  json: {
    balanceRaw: balanceRaw.toString(),
    balanceUSDT: balanceUSDT,
    balanceFormatted: "$" + balanceUSDT.toFixed(2) + " USDT",
    message: balanceUSDT === 0 
      ? "⚠️ Wallet has 0 USDT" 
      : "✅ Your wallet has $" + balanceUSDT.toFixed(2) + " USDT",
    timestamp: new Date().toISOString()
  }
}];

// Get the balance result from the HTTP Request
const balanceHex = $input.first().json.result;

// Convert from hexadecimal to decimal
const balanceWei = parseInt(balanceHex, 16);

// Convert Wei to Ether/BNB (divide by 10^18)
const balanceInEther = balanceWei / 1000000000000000000;

return [{
  json: {
    balanceWei: balanceWei.toString(),
    balance: balanceInEther,
    balanceFormatted: balanceInEther.toFixed(6) + " BNB",
    message: balanceInEther === 0 
      ? "⚠️ Wallet is empty! Add some BNB to get started." 
      : "✅ Your wallet has " + balanceInEther.toFixed(6) + " BNB",
    timestamp: new Date().toISOString()
  }
}];

// Get BTC balance (blockchain.info returns satoshis)
let balanceSatoshis = 0;

try {
  // The API returns just a number
  balanceSatoshis = parseInt($input.first().json);
} catch (error) {
  console.log("Error parsing BTC balance:", error);
}

// Convert satoshis to BTC (1 BTC = 100,000,000 satoshis)
const balanceBTC = balanceSatoshis / 100000000;

// Approximate BTC price (you can update this or use a price API later)
const btcPrice = 95000;
const balanceUSD = balanceBTC * btcPrice;

return [{
  json: {
    balanceSatoshis: balanceSatoshis,
    balanceBTC: balanceBTC,
    balanceFormatted: balanceBTC.toFixed(8) + " BTC",
    balanceUSD: balanceUSD,
    btcPrice: btcPrice,
    message: balanceBTC > 0 
      ? `✅ Bitcoin wallet: ${balanceBTC.toFixed(8)} BTC ($${balanceUSD.toFixed(2)})` 
      : "⚠️ Bitcoin wallet is empty",
    timestamp: new Date().toISOString()
  }
}];

// Get ETH balance from RPC response
const balanceHex = $input.first().json.result;

// Convert from hex to decimal (Wei)
const balanceWei = parseInt(balanceHex, 16);

// Convert Wei to ETH (1 ETH = 10^18 Wei)
const balanceETH = balanceWei / 1000000000000000000;

// Approximate ETH price
const ethPrice = 3200;
const balanceUSD = balanceETH * ethPrice;

return [{
  json: {
    balanceWei: balanceWei.toString(),
    balanceETH: balanceETH,
    balanceFormatted: balanceETH.toFixed(6) + " ETH",
    balanceUSD: balanceUSD,
    ethPrice: ethPrice,
    message: balanceETH > 0 
      ? `✅ Ethereum wallet: ${balanceETH.toFixed(6)} ETH ($${balanceUSD.toFixed(2)})` 
      : "⚠️ Ethereum wallet is empty",
    timestamp: new Date().toISOString()
  }
}];

// Get SOL balance from RPC response
const response = $input.first().json;

let balanceLamports = 0;
let balanceSOL = 0;

if (response.result && response.result.value !== undefined) {
  balanceLamports = response.result.value;
  // Convert lamports to SOL (1 SOL = 10^9 lamports)
  balanceSOL = balanceLamports / 1000000000;
}

// Approximate SOL price
const solPrice = 180;
const balanceUSD = balanceSOL * solPrice;

return [{
  json: {
    balanceLamports: balanceLamports,
    balanceSOL: balanceSOL,
    balanceFormatted: balanceSOL.toFixed(6) + " SOL",
    balanceUSD: balanceUSD,
    solPrice: solPrice,
    message: balanceSOL > 0 
      ? `✅ Solana wallet: ${balanceSOL.toFixed(6)} SOL ($${balanceUSD.toFixed(2)})` 
      : "⚠️ Solana wallet is empty",
    timestamp: new Date().toISOString()
  }
}];

const response = $input.first().json;

// XRP balance (in drops, 1 XRP = 1,000,000 drops)
let balanceDrops = 0;
let balanceXRP = 0;
let message = "⚠️ XRP wallet not found or not activated";

if (response.result && response.result.account_data && response.result.account_data.Balance) {
  balanceDrops = parseInt(response.result.account_data.Balance);
  balanceXRP = balanceDrops / 1000000;
  message = `✅ XRP wallet: ${balanceXRP.toFixed(6)} XRP`;
}

// Approximate XRP price
const xrpPrice = 2.5;
const balanceUSD = balanceXRP * xrpPrice;

return [{
  json: {
    balanceDrops: balanceDrops,
    balanceXRP: balanceXRP,
    balanceFormatted: balanceXRP.toFixed(6) + " XRP",
    balanceUSD: balanceUSD,
    xrpPrice: xrpPrice,
    message: message + ` ($${balanceUSD.toFixed(2)})`,
    accountActivated: balanceDrops > 0,
    timestamp: new Date().toISOString()
  }
}];

const accountData = $input.first().json;

// TRX balance (in SUN, 1 TRX = 1,000,000 SUN)
let balanceSun = 0;
let balanceTRX = 0;
let message = "⚠️ TRON wallet not activated";

if (accountData.balance) {
  balanceSun = accountData.balance;
  balanceTRX = balanceSun / 1000000;
  message = `✅ TRON wallet: ${balanceTRX.toFixed(6)} TRX`;
}

// Approximate TRX price
const trxPrice = 0.25;
const balanceUSD = balanceTRX * trxPrice; // <-- IMPORTANT: This line calculates USD value

return [{
  json: {
    balanceSun: balanceSun,
    balanceTRX: balanceTRX,
    balanceFormatted: balanceTRX.toFixed(6) + " TRX",
    balanceUSD: balanceUSD,  // <-- IMPORTANT: Must include this field
    trxPrice: trxPrice,
    message: message + ` ($${balanceUSD.toFixed(4)})`,
    accountActivated: balanceSun > 0,
    timestamp: new Date().toISOString()
  }
}];

// Get data using node names - with better error handling
function getBalance(nodeName) {
  try {
    const node = $(nodeName);
    if (!node || !node.first()) {
      console.log(`❌ Node '${nodeName}' not found or has no data`);
      return { balanceUSD: 0, balanceUSDT: 0, balanceFormatted: "N/A" };
    }
    const data = node.first().json;
    console.log(`✅ Got ${nodeName}:`, Object.keys(data));
    return data;
  } catch (e) {
    console.log(`❌ Error getting ${nodeName}:`, e.message);
    return { balanceUSD: 0, balanceUSDT: 0, balanceFormatted: "N/A" };
  }
}

// Get all balances
const bnb = getBalance('Convert BNB');
const usdtBEP20 = getBalance('Convert USDT');
const btc = getBalance('Convert BTC');
const eth = getBalance('Convert ETH');
const sol = getBalance('Convert SOL');
const xrp = getBalance('Convert XRP');
const trx = getBalance('Convert TRON');

// Special handling for USDT TRC20 - try multiple methods
let usdtTRC20 = { balanceUSD: 0, balanceUSDT: 0, balanceFormatted: "N/A" };

// Method 1: Try exact node name
try {
  const node = $('Convert USDT TRC20');
  if (node && node.first() && node.first().json) {
    usdtTRC20 = node.first().json;
    console.log("✅ Method 1 success - USDT TRC20 found:", usdtTRC20);
  }
} catch (e) {
  console.log("❌ Method 1 failed:", e.message);
}

// Method 2: If still not found, try getting from all items
if (!usdtTRC20.balanceUSD && !usdtTRC20.balanceUSDT) {
  try {
    const allItems = $('Convert USDT TRC20').all();
    if (allItems && allItems.length > 0) {
      usdtTRC20 = allItems[0].json;
      console.log("✅ Method 2 success - USDT TRC20 from all():", usdtTRC20);
    }
  } catch (e) {
    console.log("❌ Method 2 failed:", e.message);
  }
}

// Method 3: Try getting from pairedItem
if (!usdtTRC20.balanceUSD && !usdtTRC20.balanceUSDT) {
  try {
    const items = $input.all();
    console.log("Checking input items:", items.length);
    // Look through recent execution data
    if (items.length > 0) {
      console.log("Input item structure:", Object.keys(items[0].json));
    }
  } catch (e) {
    console.log("❌ Method 3 failed:", e.message);
  }
}

console.log("FINAL USDT TRC20 data:", usdtTRC20);

// Calculate USD values
const bnbUSD = bnb.balanceUSD || 0;
const usdtBEP20USD = usdtBEP20.balanceUSDT || usdtBEP20.balanceUSD || 0;
const btcUSD = btc.balanceUSD || 0;
const ethUSD = eth.balanceUSD || 0;
const solUSD = sol.balanceUSD || 0;
const xrpUSD = xrp.balanceUSD || 0;
const trxUSD = trx.balanceUSD || 0;
const usdtTRC20USD = usdtTRC20.balanceUSD || usdtTRC20.balanceUSDT || 0;

console.log("USD Values:", { bnbUSD, usdtBEP20USD, btcUSD, ethUSD, solUSD, xrpUSD, trxUSD, usdtTRC20USD });

const totalUSD = bnbUSD + usdtBEP20USD + btcUSD + ethUSD + solUSD + xrpUSD + trxUSD + usdtTRC20USD;

function formatUSD(value) {
  if (value === 0) return "$0.00";
  if (value < 0.01) return `$${value.toFixed(8)}`;
  if (value < 1) return `$${value.toFixed(4)}`;
  return `$${value.toFixed(2)}`;
}

const holdings = [
  { name: "TRX", value: trxUSD, formatted: trx.balanceFormatted || "N/A" },
  { name: "USDT (TRC20)", value: usdtTRC20USD, formatted: usdtTRC20.balanceFormatted || "N/A" },
  { name: "BTC", value: btcUSD, formatted: btc.balanceFormatted || "N/A" },
  { name: "ETH", value: ethUSD, formatted: eth.balanceFormatted || "N/A" },
  { name: "BNB", value: bnbUSD, formatted: bnb.balanceFormatted || "N/A" },
  { name: "SOL", value: solUSD, formatted: sol.balanceFormatted || "N/A" },
  { name: "XRP", value: xrpUSD, formatted: xrp.balanceFormatted || "N/A" },
  { name: "USDT (BEP20)", value: usdtBEP20USD, formatted: usdtBEP20.balanceFormatted || "N/A" }
];

holdings.sort((a, b) => b.value - a.value);
const activeChains = holdings.filter(h => h.value > 0).length;

return [{
  json: {
    DEBUG: {
      usdtTRC20_finalData: usdtTRC20,
      usdtTRC20_USD: usdtTRC20USD,
      allUSDValues: { bnbUSD, usdtBEP20USD, btcUSD, ethUSD, solUSD, xrpUSD, trxUSD, usdtTRC20USD },
      totalCalculated: totalUSD
    },

    portfolio: {
      "TRX (TRON)": trx.balanceFormatted || "N/A",
      "USDT (TRC20)": usdtTRC20.balanceFormatted || "N/A",
      "BTC (Bitcoin)": btc.balanceFormatted || "N/A",
      "ETH (Ethereum)": eth.balanceFormatted || "N/A",
      "BNB (BSC)": bnb.balanceFormatted || "N/A",
      "SOL (Solana)": sol.balanceFormatted || "N/A",
      "XRP (Ripple)": xrp.balanceFormatted || "N/A",
      "USDT (BEP20)": usdtBEP20.balanceFormatted || "N/A"
    },

    portfolioValue: {
      totalUSD: formatUSD(totalUSD),
      totalUSDRaw: totalUSD,
      breakdown: holdings.map(h => ({
        asset: h.name,
        value: formatUSD(h.value),
        valueRaw: h.value,
        balance: h.formatted
      }))
    },

    summary: {
      totalChains: 7,
      activeChainsWithBalance: activeChains,
      totalAssets: 8,
      totalValueUSD: totalUSD,
      largestHolding: holdings[0].value > 0 
        ? `${holdings[0].name} (${formatUSD(holdings[0].value)})` 
        : "No holdings"
    },

    message: `💰 Total Portfolio: ${formatUSD(totalUSD)} across 7 blockchains (${activeChains} active)`,

    detailedSummary: `
🏦 MULTI-CHAIN PORTFOLIO SUMMARY
═══════════════════════════════════════════════════
💰 Total Value: ${formatUSD(totalUSD)}
📊 Active Chains: ${activeChains}/7
🏆 Largest Holding: ${holdings[0].value > 0 ? holdings[0].name + ' (' + formatUSD(holdings[0].value) + ')' : 'None'}

HOLDINGS BY VALUE:
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
${holdings.map(h => {
  const indicator = h.value > 0 ? '✅' : '⚪';
  const name = h.name.padEnd(20);
  const value = formatUSD(h.value).padStart(12);
  return `${indicator} ${name} ${value}`;
}).join('\n')}
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
🕐 Updated: ${new Date().toLocaleString()}
    `.trim()
  }
}];

const accountInfo = $input.first().json;

let usdtBalance = 0;
let message = "⚠️ No USDT (TRC20) found";

// Look for USDT in TRC20 tokens
if (accountInfo.trc20token_balances && Array.isArray(accountInfo.trc20token_balances)) {
  const usdtToken = accountInfo.trc20token_balances.find(
    token => token.tokenAbbr === "USDT" || 
             token.tokenName === "Tether USD" ||
             token.tokenId === "TR7NHqjeKQxGTCi8q8ZY4pL8otSzgjLj6t"
  );

  if (usdtToken) {
    // USDT has 6 decimals on TRON
    usdtBalance = parseFloat(usdtToken.balance) / 1000000;
    message = `✅ USDT (TRC20): $${usdtBalance.toFixed(6)}`;
  }
}

return [{
  json: {
    balanceRaw: usdtBalance * 1000000,
    balanceUSDT: usdtBalance,
    balanceFormatted: "$" + usdtBalance.toFixed(6) + " USDT",
    balanceUSD: usdtBalance, // <-- IMPORTANT: USDT = $1, so balanceUSD = balanceUSDT
    network: "TRON (TRC20)",
    message: message,
    timestamp: new Date().toISOString()
  }
}];

// Get portfolio balances
const portfolio = $('Portfolio Summary').first().json;

// Get live prices from CoinGecko
const prices = $input.first().json;

console.log("Live Prices:", prices);

// Extract individual prices
const btcPrice = prices.bitcoin?.usd || 95000;
const ethPrice = prices.ethereum?.usd || 3200;
const bnbPrice = prices.binancecoin?.usd || 600;
const solPrice = prices.solana?.usd || 180;
const xrpPrice = prices.ripple?.usd || 2.5;
const trxPrice = prices.tron?.usd || 0.25;
const usdtPrice = prices.tether?.usd || 1.0;

// Get balances from portfolio
const btcBalance = portfolio.portfolioValue.breakdown[0].valueRaw || 0;
const ethBalance = portfolio.portfolioValue.breakdown[2].valueRaw || 0;
const bnbBalance = portfolio.portfolioValue.breakdown[4].valueRaw || 0;
const solBalance = portfolio.portfolioValue.breakdown[5].valueRaw || 0;
const xrpBalance = portfolio.portfolioValue.breakdown[6].valueRaw || 0;

// Get TRX and USDT balances
let trxBalance = 0;
let usdtTRC20Balance = 0;
let usdtBEP20Balance = 0;

// Extract from portfolio
portfolio.portfolioValue.breakdown.forEach(item => {
  if (item.asset === "TRX") trxBalance = item.valueRaw;
  if (item.asset === "USDT (TRC20)") usdtTRC20Balance = item.valueRaw;
  if (item.asset === "USDT (BEP20)") usdtBEP20Balance = item.valueRaw;
});

// Calculate values with LIVE prices
const btcUSD = btcBalance;
const ethUSD = ethBalance;
const bnbUSD = bnbBalance;
const solUSD = solBalance;
const xrpUSD = xrpBalance;
const trxUSD = trxBalance;
const usdtUSD = usdtTRC20Balance + usdtBEP20Balance;

const totalUSD = btcUSD + ethUSD + bnbUSD + solUSD + xrpUSD + trxUSD + usdtUSD;

// Format function
function formatUSD(value) {
  if (value === 0) return "$0.00";
  if (value < 0.01) return `$${value.toFixed(8)}`;
  if (value < 1) return `$${value.toFixed(4)}`;
  return `$${value.toFixed(2)}`;
}

// Create updated portfolio with live prices
const livePortfolio = {
  livePrices: {
    BTC: `$${btcPrice.toLocaleString()}`,
    ETH: `$${ethPrice.toLocaleString()}`,
    BNB: `$${bnbPrice.toFixed(2)}`,
    SOL: `$${solPrice.toFixed(2)}`,
    XRP: `$${xrpPrice.toFixed(4)}`,
    TRX: `$${trxPrice.toFixed(6)}`,
    USDT: `$${usdtPrice.toFixed(4)}`
  },

  portfolioValue: {
    totalUSD: formatUSD(totalUSD),
    totalUSDRaw: totalUSD,
    breakdown: {
      BTC: formatUSD(btcUSD),
      ETH: formatUSD(ethUSD),
      BNB: formatUSD(bnbUSD),
      SOL: formatUSD(solUSD),
      XRP: formatUSD(xrpUSD),
      TRX: formatUSD(trxUSD),
      USDT_Total: formatUSD(usdtUSD)
    }
  },

  holdings: portfolio.portfolio,

  priceUpdate: {
    timestamp: new Date().toISOString(),
    source: "CoinGecko API",
    refreshRate: "Real-time"
  },

  marketSummary: `💰 Portfolio: ${formatUSD(totalUSD)} | 📈 Prices Updated: ${new Date().toLocaleTimeString()}`
};

return [{
  json: livePortfolio
}];

// Get search parameters from previous node
const searchParams = $('Set Flight Search Params').first().json;

// Generate mock flight data
const flights = [
  {
    id: "FL001",
    airline: "Budget Air",
    flightNumber: "BA 001",
    departure: {
      airport: searchParams.origin,
      time: "08:00 AM",
      date: searchParams.departureDate
    },
    arrival: {
      airport: searchParams.destination,
      time: "04:30 PM",
      date: searchParams.departureDate
    },
    duration: "5h 30m",
    price: {
      USD: 0.10,
      USDT: 0.10,
      BTC: 0.0000014,
      TRX: 0.35,
      ETH: 0.000048
    },
    bookingUrl: "https://www.travala.com/book/FL001",
    cryptoAccepted: true
  },
  {
    id: "FL002",
    airline: "Economy Airlines",
    flightNumber: "EA 002",
    departure: {
      airport: searchParams.origin,
      time: "10:30 AM",
      date: searchParams.departureDate
    },
    arrival: {
      airport: searchParams.destination,
      time: "07:00 PM",
      date: searchParams.departureDate
    },
    duration: "5h 30m",
    price: {
      USD: 0.15,
      USDT: 0.15,
      BTC: 0.0000021,
      TRX: 0.54,
      ETH: 0.000072
    },
    bookingUrl: "https://www.travala.com/book/FL002",
    cryptoAccepted: true
  },
  {
    id: "FL003",
    airline: "Premium Air",
    flightNumber: "PA 003",
    departure: {
      airport: searchParams.origin,
      time: "02:15 PM",
      date: searchParams.departureDate
    },
    arrival: {
      airport: searchParams.destination,
      time: "10:45 PM",
      date: searchParams.departureDate
    },
    duration: "5h 30m",
    price: {
      USD: 0.20,
      USDT: 0.20,
      BTC: 0.0000028,
      TRX: 0.72,
      ETH: 0.000096
    },
    bookingUrl: "https://www.travala.com/book/FL003",
    cryptoAccepted: true
  }
];

// Sort by price (cheapest first)
flights.sort((a, b) => a.price.USD - b.price.USD);

return [{
  json: {
    searchParams: searchParams,
    flights: flights,
    cheapestFlight: flights[0],
    totalOptions: flights.length,
    priceRange: {
      min: flights[0].price.USD,
      max: flights[flights.length - 1].price.USD
    }
  }
}];

const flightData = $input.first().json;
const portfolio = $('Calculate Portfolio Value').first().json;

// Get portfolio balances
const portfolioUSD = portfolio.portfolioValue.totalUSDRaw || 0;
const trxBalance = portfolio.portfolioValue.breakdown?.TRX || "$0.00";
const usdtBalance = portfolio.portfolioValue.breakdown?.USDT_Total || "$0.00";

// Create detailed flight summary
const flightSummary = flightData.flights.map((flight, index) => {
  return `
Option ${index + 1}: ${flight.airline} ${flight.flightNumber}
  Route: ${flight.departure.airport} → ${flight.arrival.airport}
  Departure: ${flight.departure.date} at ${flight.departure.time}
  Arrival: ${flight.arrival.date} at ${flight.arrival.time}
  Duration: ${flight.duration}
  Price: $${flight.price.USD}

  Payment Options:
    • ${flight.price.USDT} USDT
    • ${flight.price.TRX} TRX
    • ${flight.price.BTC} BTC
    • ${flight.price.ETH} ETH
  `;
}).join('\n---\n');

const aiPrompt = `
PORTFOLIO STATUS:
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
Total Portfolio Value: $${portfolioUSD.toFixed(4)}
Available TRX: ${trxBalance}
Available USDT: ${usdtBalance}
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

FLIGHT SEARCH:
From: ${flightData.searchParams.origin}
To: ${flightData.searchParams.destination}
Date: ${flightData.searchParams.departureDate}
Return: ${flightData.searchParams.returnDate}

AVAILABLE FLIGHTS:
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━
${flightSummary}
━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━

ANALYSIS REQUIREMENTS:
1. Can I afford ANY of these flights with my current portfolio?
2. Which flight offers the best value (price vs timing)?
3. What's the best payment method based on my holdings?
4. Should I book now or wait?
5. What percentage of my portfolio would this use?

RESPOND WITH VALID JSON ONLY:
{
  "decision": "yes" or "no",
  "selectedFlight": "FL001" or "FL002" or "FL003" or null,
  "paymentMethod": "USDT" or "TRX" or "BTC" or "ETH" or null,
  "paymentAmount": number or null,
  "portfolioImpact": "percentage",
