    if (d.data.aiDecision === "yes" || d.data.aiDecision === "partial") {
      approvedCount++;
    } else {
      rejectedCount++;
    }
  } catch(e) {
    errorCount++;
    d.data = { aiDecision: "error", aiReason: "Node failed to execute" };
  }
});

// System health metrics
const totalDecisions = decisions.length;
const successfulExecutions = totalDecisions - errorCount;
const successRate = ((successfulExecutions / totalDecisions) * 100).toFixed(1);

const metrics = {
  totalDecisions: totalDecisions,
  approved: approvedCount,
  rejected: rejectedCount,
  errors: errorCount,
  successRate: successRate,
  portfolioValue: portfolio.portfolioValue.totalUSD,
  lastRun: startTime.toISOString()
};

// Create decision breakdown table
const decisionHTML = decisions.map(d => {
  let statusBadge, statusColor;

  if (d.data.aiDecision === "yes" || d.data.aiDecision === "partial") {
    statusBadge = "✅ APPROVED";
    statusColor = "#28a745";
  } else if (d.data.aiDecision === "no") {
    statusBadge = "❌ REJECTED";
    statusColor = "#dc3545";
  } else {
    statusBadge = "⚠️ ERROR";
    statusColor = "#ffc107";
  }

  const reason = d.data.aiReason || "No reason provided";

  return `
    <tr>
      <td style="padding: 12px; border-bottom: 1px solid #ddd;">${d.name}</td>
      <td style="padding: 12px; border-bottom: 1px solid #ddd; color: ${statusColor}; font-weight: bold;">${statusBadge}</td>
      <td style="padding: 12px; border-bottom: 1px solid #ddd; font-size: 12px; color: #666;">${reason}</td>
    </tr>
  `;
}).join('');

